int main() {
    string input1,input2;
    getline(cin, input1);
    getline(cin, input2);
    // 存储区间
    vector<pair<int, int>> ans;

    // 处理区间输入字符串 [18,30],[33,40] => 18,30],[33,40
    input1 = input1.substr(1,input1.size() - 2);
    vector<string> tmpArr = split(input1, "],[");
    for (int i = 0; i < tmpArr.size(); i++) {
        string tmp = tmpArr[i];
        vector<string> startAndEnd = split(tmp, ",");
        int start = stoi(startAndEnd[0]);
        int end = stoi(startAndEnd[1]);
        ans.push_back({start, end});
    }
​
    // 处理连接器输入字符串
    input2 = input2.substr(1, input2.size() - 2);
    vector<string> joinStrArr = split(input2, ",");
    vector<int> joinArr;
    for (int i = 0; i < joinStrArr.size(); i++) {
        joinArr.push_back(stoi(joinStrArr[i]));
    }
​
    // 输入数据区间进行区间合并
    vector<pair<int, int>> merge = merged(ans);
​
    // 计算每个相邻区间之间的距离
    vector<int> dist;
    for (int i = 1; i < merge.size(); i++) {
        dist.push_back(merge[i].first - merge[i-1].second);
    }
    sort(dist.begin(), dist.end());
    sort(joinArr.begin(), joinArr.end());

​
    int i = dist.size() - 1,j = joinArr.size() -1;
    // 合并次数
    int count = 0;
    // 贪心优先把连接器数量大的分配给距离大
    while (i >= 0 && j >= 0) {
        if (dist[i] <= joinArr[j]) {
            count++;
            i--;
            j--;
        } else {
            i--;
        }
    }
    // 区间数 - 合并
    cout << dist.size() + 1 - count;
    return 0;
}
