    // 区间合并函数
    public static List<int[]> merged(List<int[]> segs) {
        // 按起点排序
        segs.sort(Comparator.comparingInt(a -> a[0]));
        List<int[]> merged = new ArrayList<>();
        int[] cur = segs.get(0);
        int n = segs.size();
        for (int i = 1; i < n; i++) {
            if (segs.get(i)[0] <= cur[1]) {
                cur[1] = Math.max(cur[1], segs.get(i)[1]);
            } else {
                merged.add(cur);
                cur = segs.get(i);
            }
        }
        merged.add(cur);
        return merged;
    }
