package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// 合并区间函数
func merged(segs [][2]int) [][2]int {
    sort.Slice(segs, func(i, j int) bool {
        return segs[i][0] < segs[j][0]
    })
    var result [][2]int
    cur := segs[0]
    for i := 1; i < len(segs); i++ {
        if segs[i][0] <= cur[1] {
            if segs[i][1] > cur[1] {
                cur[1] = segs[i][1]
            }
        } else {
            result = append(result, cur)
            cur = segs[i]
        }
    }
    result = append(result, cur)
    return result
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    input1, _ := reader.ReadString('\n')
    input2, _ := reader.ReadString('\n')
    input1 = strings.TrimSpace(input1)
    input2 = strings.TrimSpace(input2)
​
    // 去掉最外层中括号
    input1 = input1[1 : len(input1)-1]
    parts := strings.Split(input1, "],[")
    var segments [][2]int
    for _, s := range parts {
        nums := strings.Split(s, ",")
        start, _ := strconv.Atoi(nums[0])
        end, _ := strconv.Atoi(nums[1])
        segments = append(segments, [2]int{start, end})
    }
​
    // 解析连接器
    input2 = input2[1 : len(input2)-1]
    joinStrs := strings.Split(input2, ",")
    var joinArr []int
    for _, s := range joinStrs {
        num, _ := strconv.Atoi(s)
        joinArr = append(joinArr, num)
    }
​
    // 合并区间
    mergedSegs := merged(segments)
​
    // 计算相邻区间之间的距离
    var dist []int
    for i := 1; i < len(mergedSegs); i++ {
        d := mergedSegs[i][0] - mergedSegs[i-1][1]
        dist = append(dist, d)
    }
​
    sort.Ints(dist)
    sort.Ints(joinArr)
​
    i, j := len(dist)-1, len(joinArr)-1
    count := 0
    for i >= 0 && j >= 0 {
        if dist[i] <= joinArr[j] {
            count++
            i--
            j--
        } else {
            i--
        }
    }
​
    // 输出最终可合并后的区间数
    fmt.Println(len(dist) + 1 - count)
}
